python3 -c "
import glob,os,re
cs=[]
for d in glob.glob(os.path.expanduser('~/Projects/*/inbox'))+glob.glob(os.path.expanduser('~/Projects/*/*.inbox'))+glob.glob(os.path.expanduser('~/Projects/*/*/inbox/restarts_inbox'))+glob.glob(os.path.expanduser('~/Projects/*/inbox/restarts_inbox')):
  for f in glob.glob(os.path.join(d,'*.md')):
    try:
      h=open(f,errors='ignore').read(800)
    except Exception:
      continue
    if re.search(r'category:\s*session-restart',h) and re.search(r'status:\s*open',h): cs.append((os.path.getmtime(f),f))
p='/tmp/restart_prompt_latest.md'
if cs:
  n=sorted(cs)[-1][1]; open(p,'w').write(open(n,errors='ignore').read())
elif os.path.exists(p):
  os.remove(p)
" 2>/dev/null || true

